alter table public.inventory_transactions add column if not exists created_by_name text;create or replace function public.stamp_inventory_actor() returns trigger language plpgsql security definer set search_path=public as $$ begin select full_name into new.created_by_name from public.profiles where id=new.created_by;return new;end $$;drop trigger if exists inventory_tx_stamp_actor on public.inventory_transactions;create trigger inventory_tx_stamp_actor before insert on public.inventory_transactions for each row execute function public.stamp_inventory_actor();revoke all on function public.stamp_inventory_actor() from public,anon,authenticated;